from pathlib import Path
import re
for lang in ('zh','en'):
 zh=lang=='zh'
 for p in [x for x in (Path(lang)/'models').glob('*.html') if x.stem=='qwq-32b' or x.stem.startswith('qwen')]:
  slug=p.stem
  foot=f'''<footer class="q-footer"><div class="q-wrap"><div class="q-footer-top"><div class="q-footer-brand"><a class="q-brand" href="/">AnyAIGC</a><p>{'国内外大模型 API 中转平台。一个 Base URL、一个 API Key，统一调用 300+ 模型。' if zh else 'An API gateway for global AI models. One base URL and one API key for 300+ models.'}</p></div><div class="q-footer-cols"><section><h2>{'产品' if zh else 'Product'}</h2><a href="/{lang}/models/">{'模型专题' if zh else 'Model guides'}</a><a href="https://anyaigc.ai/pricing">{'模型广场' if zh else 'Model catalog'}</a><a href="https://anyaigc.ai/console">{'控制台' if zh else 'Console'}</a></section><section><h2>{'资源' if zh else 'Resources'}</h2><a href="https://docs.anyaigc.ai" target="_blank" rel="noopener">{'API 文档 ↗' if zh else 'API docs ↗'}</a><a href="https://docs.anyaigc.ai/tutorials/plugins-7010249" target="_blank" rel="noopener">Codex {'教程 ↗' if zh else 'guide ↗'}</a><a href="https://anyaigc.ai/customersupport">{'联系我们' if zh else 'Contact us'}</a></section><section><h2>{'条款' if zh else 'Legal'}</h2><a href="/privacy">{'隐私政策' if zh else 'Privacy policy'}</a><a href="/terms">{'服务条款' if zh else 'Terms of service'}</a></section></div></div><div class="q-footer-bottom"><p>{'© 2026 AnyAIGC。千问（Qwen）是阿里云的商标。AnyAIGC 是独立的 API 服务商，与其无隶属关系。模型许可与商用条款以千问官方条款为准。' if zh else '© 2026 AnyAIGC. Qwen is a trademark of Alibaba Cloud. AnyAIGC is an independent API provider and is not affiliated with Alibaba Cloud. Model licenses and commercial terms are governed by Qwen official terms.'}</p><a class="q-footer-lang" href="/{'en' if zh else 'zh'}/models/{slug}" hreflang="{'en' if zh else 'zh-CN'}">{'English' if zh else '中文'}</a></div></div></footer>'''
  s=p.read_text(encoding='utf8');s=re.sub(r'<footer class="q-footer">.*?</footer>',foot,s,flags=re.S);p.write_text(s,encoding='utf8',newline='\n')
